// Package api holds infraweave's API descriptions.
//
// deploy.openapi.yaml is the API infraweave serves, bundled by
// tools/openapi-bundle from the fragments in src/deploy. The Spacelift
// reference under reference/spacelift is generated by tools/specref; it
// describes the upstream surface infraweave mirrors, not the API it serves.
// parity-baseline.json accepts the reference operations deploy.openapi.yaml
// does not serve unchanged, and parity_test.go fails when it accepts too
// little or too much; make parity-baseline rewrites it.
package api

import _ "embed"

// SpaceliftReference is the generated REST projection of the Spacelift API.
//
//go:embed reference/spacelift/spacelift.openapi.yaml
var SpaceliftReference []byte

// Deploy is the bundled deploy API that infraweave serves under /api/v1.
//
//go:embed deploy.openapi.yaml
var Deploy []byte
